<script lang="ts">
 import {onMount} from 'svelte';import {api,demo,errorMessage} from '../store.svelte';
 let details=$state<any>(null),busy=$state(false),error=$state(''),confirmed=$state(false),verification=$state(''),completed=$state(false),nonce='';
 onMount(()=>{nonce=new URLSearchParams(location.search).get('code')??'';api('/api/auth/qr/request?code='+encodeURIComponent(nonce)).then(result=>details=result).catch(cause=>error=errorMessage(cause));});
 async function approve(){if(busy||!confirmed)return;busy=true;error='';try{await api('/api/auth/qr/approve',{method:'POST',body:JSON.stringify({code:nonce,confirmed,verificationCode:verification})});completed=true;nonce='';history.replaceState({},'',location.pathname);}catch(cause){error=errorMessage(cause);}finally{busy=false;}}
</script>
<div class="approval-shell"><section class="card padded"><a class="brand" href="/"><img class="brand-mark" src="/aswired-logo.gif" alt=""/><strong>ASWired</strong></a><h1>{completed?'已确认登录':'确认浏览器登录'}</h1>{#if completed}<p class="muted space-top">请回到原浏览器继续。当前手机仍保留原来的登录身份。</p><a class="button space-top" href="/portal">返回我的套餐</a>{:else if details}<p class="muted space-top">使用账户 <strong>{demo.user?.username}</strong> 登录 {details.deviceName}。</p><p class="hint">工作区：{details.origin}</p><label class="field space-top">原浏览器显示的六位确认码<input maxlength="6" autocomplete="off" bind:value={verification}/></label><label class="tag space-top"><input type="checkbox" bind:checked={confirmed}/>这是我本人正在使用并发起登录的浏览器</label><div class="actions space-top"><a class="button" href="/">取消</a><button class="button primary" disabled={busy||!confirmed||verification.trim().length!==6} onclick={approve}>确认登录</button></div>{:else if !error}<p class="muted space-top">正在读取扫码请求…</p>{/if}{#if error}<p class="error space-top" role="alert">{error}</p><a class="button space-top" href="/">返回工作区</a>{/if}</section></div>
<style>.approval-shell{min-height:100dvh;display:grid;place-items:center;padding:1.2rem}.approval-shell section{width:min(100%,30rem)}.approval-shell .brand{padding:0;margin-bottom:1.5rem}.approval-shell h1{font-size:1.7rem}.approval-shell .tag{display:flex;gap:.5rem;align-items:flex-start;padding:.65rem}</style>
